var apiUtils = require("@node-red/editor-api/lib/util");
var utilApi = require("@node-red/util");
var typedb = require("@node-red/editor-api/lib/admin/typedb")
var runtime;

let parent_backdoors = []
let up = []
let down = []
let parent_child_idx = {}
let collider_paths = {}
let localhost_uri = "http://127.0.0.1"
let docker_backend_uri = "http://localhost"
let port = "5000"

async function getCausalStrengthEdges(req, res) {
    console.log("@getCausalStrengthEdges")
    let opts = req.body
    // retrieve model name
    let edge_strength = {}
    let intrinsic_effects = {}
    let causal_mechanisms = {}
    let flow_info = runtime._.flows.getFlow(opts.activeWorkspace)

    try {
        // match the nrid of the causal path : Typ
        for await (let node of flow_info.nodes) {
            console.log("--------" + node.name + " - " + node.id + "-------")
            if (node.type === "causeeffect") {
                let cause_n = node.id
                let effect_n = node.id

                console.log("lenth of children ", node.wires[0].length)
                // child node 
                // for await (let child of node.wires[0]) {
                let match = "match $cp isa causeeffect, has nrid \"" +node.id+ "\";\n"

                // child = runtime._.nodes.getNode(child)
                // // console.log("child: ", child)
                // if (child.type === "causeeffect") {
                //     effect_n = child.id
                //     match = match + cause_n + "_" + effect_n + "\";\n"
                // }
                // if (child.type === "probability") {
                //     effect_n = child.id
                //     match = match + child.id + "\";\n"
                // }
                let opts = {
                    "db": "causeway-repo",
                    "query": match,
                    "query_type": "match",
                    "session_type": "DATA",
                    "transaction_type": "READ"
                }
                console.log("match statement: ", match)
                // let typedb api handle executing query
                let query_result = await typedb.executeQuery(opts)
                // get transaction type instance for access to remote concepts functionality
                let tx = await typedb.get_transaction()

                console.log('query result', query_result.length)
                console.log("~~transaction is open:  ", tx.isOpen())
                // // iterate through results; should be of length 1 
                for await (let result of query_result) {
                    let causal_path = await result.get("cp").asRemote(tx)
                    let attributes = await causal_path.getHas().collect()
                    console.log("length of attributes: ", attributes.length)
                    for await (let attribute of attributes) {
                        console.log("Attribute label type: ", attribute.type.label)
                        if (attribute.type.label.name === "edge_strength") {
                            attribute_value = attribute.value.split(":")
                            console.log("node id: ", effect_n)
                            console.log("attribute value: ", attribute_value)
                            if (edge_strength[effect_n]) {
                                edge_strength[effect_n] = { ...edge_strength[effect_n], [attribute_value[0]]: attribute_value[1] }
                            } else {
                                edge_strength[effect_n] = { [attribute_value[0]]: attribute_value[1] }
                            }
                            console.log(edge_strength)
                        }
                        if (attribute.type.label.name === "intrinsic_effects") {
                            if (intrinsic_effects[effect_n]) {
                                intrinsic_effects[effect_n].push(attribute.value)
                            } else {
                                intrinsic_effects[effect_n] = [attribute.value]
                            }
                        }
                        if (attribute.type.label.name === "causal_mechanisms") {
                            if (causal_mechanisms[effect_n]) {
                                causal_mechanisms[effect_n].push(attribute.value)
                            }
                            else {
                                causal_mechanisms[effect_n] = [attribute.value]
                            }
                        }
                    }
                }
                await typedb.close_transaction(opts.transaction_type)
                // } end of child wire iteration
            }
        }

        return [edge_strength, intrinsic_effects, causal_mechanisms]
    } catch (exception) {
        console.log(exception)
    }
}




module.exports = {
    init: function (_runtime) {
        runtime = _runtime;
        console.log("Causeway runtime functionality : ", runtime.causeway)
    },
    getCausalStrengthEdges: getCausalStrengthEdges,
    getPyWhyInfo: async function (req, res) {
        try {
            pywhy_info = {
                "pywhy-gcm": {
                    "edge_strength": {},
                    "causal_mechanisms": {},
                    "intrinsic_effects": {}
                }
            }

            console.log(" ~~~~~~~~~ /causeway/getPyWhyInfo ~~~~~~~~~ ")
            let [edge_strength, intrinsic_effects, causal_mechanisms] = await getCausalStrengthEdges(req, res)
            console.log("Edge Strength: ", edge_strength)
            console.log("Intrinsic Effects: ", intrinsic_effects)
            console.log("Causal Mechanisms: ", causal_mechanisms)

            pywhy_info["pywhy-gcm"] = {
                ...pywhy_info["pywhy-gcm"],
                ["edge_strength"]: edge_strength,
                ["intrinsic_effects"]: intrinsic_effects,
                ["causal_mechanisms"]: causal_mechanisms,

            }
            res.send(pywhy_info)
        } catch (exception) {
            // res.send(exception)
        }
    }
}




